1	// =============================================================================
2	// M5 Pipeline — CLI 入口 + 统一导出
3	// =============================================================================
4	
5	import { PipelineOrchestrator } from './orchestrator';
6	import type { PipelineOptions, PipelineResult } from './orchestrator';
7	
8	export { PipelineOrchestrator };
9	export type { PipelineOptions, PipelineResult };
10	
11	// =============================================================================
12	// CLI 入口函数
13	// =============================================================================
14	
15	/**
16	 * 简单的命令行参数解析器。
17	 * 支持 --key=value 和 --key value 两种格式。
18	 */
19	function parseArgv(argv: string[]): Record<string, string> {
20	  const args: Record<string, string> = {};
21	  for (let i = 2; i < argv.length; i++) {
22	    const arg = argv[i];
23	
24	    // --key=value form
25	    if (arg.startsWith('--') && arg.includes('=')) {
26	      const eqIdx = arg.indexOf('=');
27	      const key = arg.slice(2, eqIdx);
28	      const value = arg.slice(eqIdx + 1);
29	      args[key] = value;
30	      continue;
31	    }
32	
33	    // --key value form
34	    if (arg.startsWith('--') && i + 1 < argv.length) {
35	      const key = arg.slice(2);
36	      const value = argv[i + 1];
37	      args[key] = value;
38	      i++; // skip next arg (the value)
39	    }
40	  }
41	  return args;
42	}
43	
44	/**
45	 * CLI 入口 — 解析命令行参数并执行管道。
46	 *
47	 * 用法:
48	 *   ts-node src/pipeline/index.ts
49	 *   ts-node src/pipeline/index.ts --date=2026-06-01
50	 *   ts-node src/pipeline/index.ts --date=2026-06-01 --stage=extract
51	 *   ts-node src/pipeline/index.ts --data-dir=./my-data --parallel=5
52	 *
53	 * 命令行参数:
54	 *   --date=YYYY-MM-DD    处理日期
55	 *   --stage=阶段         起始阶段 (ingest|extract|synthesize|visualize)
56	 *   --data-dir=<path>    data/raw 目录路径
57	 *   --parallel=<n>       M2 并发数
58	 */
59	export async function main(args?: string[]): Promise<void> {
60	  const argv = args ?? process.argv;
61	  const parsed = parseArgv(argv);
62	
63	  const options: PipelineOptions = {};
64	
65	  if (parsed.date) {
66	    options.date = parsed.date;
67	  }
68	
69	  if (parsed.stage) {
70	    const validStages = ['ingest', 'extract', 'synthesize', 'visualize'];
71	    if (validStages.includes(parsed.stage)) {
72	      options.stage = parsed.stage as PipelineOptions['stage'];
73	    } else {
74	      console.error(`[ERROR] Invalid stage: ${parsed.stage}. Must be one of: ${validStages.join(', ')}`);
75	      process.exit(1);
76	    }
77	  }
78	
79	  if (parsed['data-dir']) {
80	    options.dataDir = parsed['data-dir'];
81	  }
82	
83	  if (parsed.parallel) {
84	    const n = parseInt(parsed.parallel, 10);
85	    if (!isNaN(n) && n > 0) {
86	      options.maxParallel = n;
87	    } else {
88	      console.error(`[ERROR] Invalid parallel value: ${parsed.parallel}. Must be a positive number.`);
89	      process.exit(1);
90	    }
91	  }
92	
93	  const orchestrator = new PipelineOrchestrator(options);
94	  const result = await orchestrator.run();
95	
96	  // Output results
97	  console.log(JSON.stringify(result, null, 2));
98	
99	  // Exit with error code on overall failure
100	  if (!result.success) {
101	    process.exit(1);
102	  }
103	}
104	
105	// =============================================================================
106	// Self-execution when run directly
107	// =============================================================================
108	
109	// Check if this script is being run directly (not imported)
110	const isMainModule =
111	  typeof process !== 'undefined' &&
112	  process.argv.length >= 2 &&
113	  (process.argv[1] === __filename || process.argv[1]?.endsWith('/pipeline/index.ts') || process.argv[1]?.endsWith('\\pipeline\\index.ts'));
114	
115	if (isMainModule) {
116	  main().catch((err) => {
117	    console.error('[FATAL] Pipeline crashed:', err);
118	    process.exit(1);
119	  });
120	}
